const {routeForSource} = require('./docs-narrative-audit-contract');

function review(source_file, source_sha256, progressive, prerequisites, consistency, accuracy, completeness) {
  return {
    source_file,
    route: routeForSource(source_file),
    source_sha256,
    verdict: 'pass',
    dimensions: {
      progressive_disclosure: {status: 'pass', evidence: progressive},
      prerequisites: {status: 'pass', evidence: prerequisites},
      internal_consistency: {status: 'pass', evidence: consistency},
      contract_accuracy: {status: 'pass', evidence: accuracy},
      user_facing_completeness: {status: 'pass', evidence: completeness},
    },
  };
}

